header {

    nav {
       display: flex;
       justify-content: space-between;
       align-items: center;
       position: relative;
       padding-top: 40px;

       .logo {
           font-size: 42px;
           position: relative;
           font-family: 'Pacifico';
           margin: 0;
           padding: 0;
           cursor: pointer;
           bottom: 6px;
       }

       .navigation {
           display: flex;
           align-items: flex-end;
           padding: 0;
           
           .nav-item {
               display: block;
               padding: 0;
               margin: 0 55px 0 0;
               text-align: center;

                p {
                    text-align: left;
                }

                .nav-item-desc {
                    color: $lightgrey;
                    font-family: 'Bebas';
                    margin: 0;
                    padding: 0 0 3px 0;
                    font-weight: 300;
                    font-size: 17px;
                    letter-spacing: normal;
                }
                .nav-item-head {
                    font-size: 24px;
                    font-family: 'Bebas';
                    margin: 0;
                    padding: 0;
                    letter-spacing: normal;
                }

                &:last-child {
                    margin: 0;
                }
           }
       }
    }
}

.featured-works {
    padding: 50px 0 70px 0;

    .works-slider {
        position: relative;
        width: 100%;
        height: 423px;

        .slide-picture {
            position: relative;
            width: 100%;
            height: 100%;

            .title {
                padding: 14px 17px 10px 17px;
                background-color: #404040;
                display: inline-block;
                position: absolute;
                bottom: 0;
                left: 0;

                h5 {
                    color: $grey;
                    font-weight: 500;
                    line-height: 0.9;
                    font-size: 17px;
                    padding-bottom: 2px;
                }
                h1 {
                    font-size: 35px;
                    color: $white;
                    font-weight: 500;
                    line-height: 0.9;
                }
            }

            .slider-arrow {
                position: absolute;
                width: 22px;
                height: auto;
                bottom: -1px;
                left: 50%;
            }

            img {
                width: 100%;
                height: 100%;
                object-fit: cover;
            }
        }

        .slider-indicators {
            position: absolute;
            right: 13px;
            bottom: 12px;
            width: 115px;
            height: 5px;
            display: flex;

            .slider-indicator {
                width: 23px;
                height: 5px;
                background-color: $white;
                display: block;
                margin-right: 7px;
                cursor: pointer;

                &:last-child {
                    margin-right: 0;
                }
            }

            .active {
                opacity: 0.15;
                cursor: auto;
            }
        }
    }

    .description {
        width: 100%;
        padding: 17px 0 20px 16px;
        background: url('../../../../images/Home/Description-bg.png') no-repeat center center;
        background-size: cover;

        h4 {
            font-weight: 500;
            margin: 0;
            padding: 0 0 10px 0;
        }

        p {
            font-weight: 400;
            margin: 0;
            padding: 0;
            line-height: 1.3;
        }
    }
}

.project-cards {
    display: flex;
    padding: 0 0 70px 0;

    .card {
        width: 300px;
        margin-right: 20px;
        padding-right: 10px;

        .card-head {
            margin-bottom: 30px;
            display: flex;

            .icon {
                width: 85px;
                height: 45px;
                display: block;
                margin-right: 20px;
            }

            .i1 {
                background: url('../../../../images/Home/search-icon.png') no-repeat 7px 0;
            }
            .i2 {
                background: url('../../../../images/Home/star-icon.png') no-repeat 7px 0;
            }
            .i3 {
                background: url('../../../../images/Home/message-icon.png') no-repeat 7px 2px;
                background-size: 43px 41px;
                margin-right: 32px;
            }

            h3 {
                font-size: 25px;
                font-weight: 600;
            }
        }

        .card-body {
            margin-bottom: 40px;
            line-height: normal;
        }

        .card-link {
            font-family: 'Bebas';
            font-size: 17px;
            display: flex;
            align-items: center;

            .arrow-icon {
                width: 17px;
                height: 9px;
                display: block;
                background: url('../../../../images/Home/more-icon.png') no-repeat center;
                margin-right: 10px;
            }

            &:hover {
                .arrow-icon {
                    transition: all 0.15s;
                    transform: translateX(3px);
                }
            }
        }

        &:last-child {
            margin-right: 0;
        }
    }
}

.latest-work {
    padding: 0 0 70px 0;

    .work-head {
        width: 100%;
        height: 48px;
        display: flex;
        align-items: center;
        margin-bottom: 55px;
        background: url('../../../../images/Home/Header-Background.png') no-repeat center center;
        background-size: cover;

        h3 {
            box-sizing: content-box;
            padding: 0 30px;
            display: inline-block;
            margin: 0 auto;
            height: 100%;
            line-height: 48px;
            background-color: $white;
        }
    }

    .work-cards {
        display: flex;

        .card {
            width: 220px;
            margin-right: 20px;

            .card-img {
                width: 100%;
                height: 120px;
                border: 2px solid #f0f0f0;
                overflow: hidden;

                img {
                    width: 100%;
                    height: 100%;
                    object-fit: cover;
                    transition: all 0.3s ease-in-out;
                }
            }
            
            .card-content {
                width: 100%;
                padding: 18px 4px 0 2px;

                h5 {
                    padding-bottom: 18px;
                    font-size: 19px
                }

                p {
                    margin-bottom: 18px;
                    line-height: normal;
                }

                .card-link {
                    font-family: 'Bebas';
                    font-size: 17px;
                    display: flex;
                    align-items: center;
        
                    .arrow-icon {
                        width: 17px;
                        height: 9px;
                        display: block;
                        background: url('../../../../images/Home/more-icon.png') no-repeat center;
                        margin-right: 10px;
                        transition: all 0.15s ease-in-out;
                    }
        
                    &:hover {
                        .arrow-icon {
                            transform: translateX(3px);
                        }
                    }
                }
            }

            &:last-child {
                margin-right: 0;
            }

            &:hover {
                .card-img {
            
                    img {
                        transform: scale(1.1);
                    }
                }
            }
        }
    }
}

footer {  
    background-color: #f6f6f6;

    .footer-border {
        height: 5px;
        width: 100%;
        background: url('../../../../images/Home/footer-border.png') no-repeat center center;
    }

    .footer {
        padding: 24px 0 37px 0;
        display: flex;
        justify-content: space-between;

        p {
            font-size: 15px;
            color: $grey;

            span,a {
                color: #6e6e6e;
            }

            a {
                &:hover {
                    text-decoration: underline;
                }
            }
        }
    }
}
